const data=$input.first().json;
const config=$('Workflow Config').first().json;
return [{json:{...data,demo_scenario:config.body?.demo_scenario||'normal'}}];

const TOLERANCE = 0.01;
return $input.all().map((entry) => {
  const order = entry.json;
  const errors = [];

  // Customer and address
  if (!order.customer || !order.customer.email) errors.push('Missing customer or email');
  const addr = order.shipping_address || {};
  if (!addr.street || !addr.city || !addr.postal_code || !addr.country) errors.push('Incomplete shipping address');

  // An already-reserved packing order may be handed between the order event and logistics flows.
  const reservationAlreadyStarted = order.status === 'packing' && order.inventoryReserved === true;
  if (order.status !== 'ready_for_shipment' && !reservationAlreadyStarted) {
    errors.push('Invalid order status: ' + (order.status || 'missing') + ' (expected ready_for_shipment or an already-reserved packing order)');
  }

  // 2. Products
  const products = Array.isArray(order.products) ? order.products : [];
  if (products.length === 0) errors.push('No products in order');
  let computedTotal = 0;
  products.forEach((p, i) => {
    const item = p || {};
    const label = 'Product #' + (i + 1) + (item.sku ? ' (' + item.sku + ')' : '');
    if (!item.sku) errors.push(label + ': missing sku');
    if (!item.name) errors.push(label + ': missing name');
    const qty = Number(item.qty);
    const qtyOk = item.qty !== undefined && item.qty !== null && item.qty !== '' && Number.isFinite(qty) && qty > 0;
    if (!qtyOk) errors.push(label + ': quantity must be greater than 0');
    const price = Number(item.price);
    const priceOk = item.price !== undefined && item.price !== null && item.price !== '' && Number.isFinite(price) && price >= 0;
    if (!priceOk) errors.push(label + ': price must be 0 or more');
    if (qtyOk && priceOk) computedTotal += qty * price;
  });
  computedTotal = Math.round(computedTotal * 100) / 100;

  // 3. Order total = sum(qty x price)
  const total = Number(order.total_amount);
  if (!Number.isFinite(total) || total <= 0) {
    errors.push('Total amount must be greater than 0');
  } else if (Math.abs(computedTotal + Number(order.shipping_amount || 0) - total) > TOLERANCE) {
    errors.push('Order total mismatch (computed ' + computedTotal.toFixed(2) + ' vs order ' + total.toFixed(2) + ')');
  }

  // 4. Payment
  if (order.payment_status !== 'paid') errors.push('Payment not completed (payment_status: ' + (order.payment_status || 'missing') + ')');
  if (!order.currency) errors.push('Missing currency');
  if (order.paid_amount !== undefined && order.paid_amount !== null) {
    const paid = Number(order.paid_amount);
    if (!Number.isFinite(paid) || (Number.isFinite(total) && Math.abs(paid - total) > TOLERANCE)) {
      errors.push('Paid amount mismatch (paid ' + order.paid_amount + ' vs total ' + order.total_amount + ')');
    }
  }

  return { json: { ...order, computed_total: computedTotal, isValid: errors.length === 0, validationErrors: errors } };
});

return $input.all().map((entry) => {
  const order = entry.json;
  const duplicate = Boolean(order.shipment_id || order.shipment);
  const errors = [...(order.validationErrors || [])];
  if (duplicate) errors.push('Duplicate order: ' + order.id + ' already has a shipment');
  return { json: { ...order, duplicate, validationErrors: errors, isValid: order.isValid === true && !duplicate } };
});

// MOCK hand-off of the validated order to the Inventory & Warehouse process (DEMO).
const order = $json;
const products = (order.products || []).map((p) => ({ sku: p.sku, name: p.name, qty: Number(p.qty) }));
const quantities = {};
products.forEach((p) => { quantities[p.sku] = p.qty; });
return [{ json: {
  order_id: order.id,
  customer: order.customer,
  shipping_address: order.shipping_address,
  products,
  quantities,
  total_amount: order.total_amount,
  currency: order.currency,
  handoff_status: 'sent_to_warehouse',
  sent_at: new Date().toISOString(),
} }];

const event=$input.first().json.body||{};
if(!event.order_id && !event.order?.id) return [];
if(event.type && !['order.created','order.validated','order.confirmed','order.cancelled','order.shipped','shipment.updated','payment.reconciled','inventory.reserved','warehouse.ready','warehouse.updated','order.review_required'].includes(event.type))return [];
return [{json:{event,orderId:String(event.order_id||event.order.id),shopBaseUrl:'https://erik-unbarking-foolhardily.ngrok-free.dev',logisticsWebhookUrl:'https://cosmos-team-5ia.app.n8n.cloud/webhook/order-ready-for-shipment'}}];

const context = $input.first().json;
const messages = Array.isArray(context.messages) ? context.messages : [];
const reconstructedThread = messages.map((message) => {
  const role = String(message.role || 'customer').toUpperCase();
  const createdAt = message.at || '';
  const content = String(message.content || message.message || '');
  return `${role} (${createdAt}): ${content}`;
}).join('\n');
return [{json:{...context,reconstructedThread,messageCount:messages.length,threadReconstructed:messages.length > 0}}];
